function changeDetails(change:Change){const before=change.before_state,after=change.after_state;if(!before||!after)return change.change_type==='admission'?'Entrada na equipe registrada.':'';const fields:[string,string][]=[['job_title','Cargo'],['seniority','Senioridade'],['department','Departamento'],['team_area','Setor'],['manager_code','Gestor'],['employment_type','Vínculo'],['weekly_hours','Jornada semanal'],['status','Situação']];return fields.filter(([key])=>String(before[key]??'')!==String(after[key]??'')).map(([key,label])=>`${label}: ${String(before[key]??'—')} → ${String(after[key]??'—')}`).join(' · ')||'Atualização dos dados da ficha, sem mudança de cargo ou área.';}
function currentMonth(){const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit'}).formatToParts(new Date());return `${parts.find(part=>part.type==='year')?.value}-${parts.find(part=>part.type==='month')?.value}`;}
function monthLabel(month:string){const [y,m]=month.split('-').map(Number);return new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(new Date(y,m-1,1));}
function dateLabel(s?:string|null){if(!s)return'—';return s.includes('T')?new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo'}).format(new Date(s)):new Intl.DateTimeFormat('pt-BR').format(new Date(`${s.slice(0,10)}T12:00:00`));}
const avatarSources={female:'data:image/webp;base64,',male:'data:image/webp;base64,',neutral:'data:image/webp;base64,'} as const;
function TeamAvatar({name,style='neutral',large=false}:{name:string;style?:'female'|'male'|'neutral';large?:boolean}){return <span className={`team-avatar team-avatar-image ${style} ${large?'large':''}`} title={`Avatar padrão de ${name}`} aria-hidden="true"><img src={avatarSources[style]||avatarSources.neutral} alt=""/></span>}
function TrendChart({series}:{series:{month:string;active:number}[]}){const max=Math.max(1,...series.map(point=>point.active));const points=series.map((point,i)=>({x:series.length===1?220:24+(i*(392/(series.length-1))),y:144-(point.active/max)*92,...point}));const line=points.map((point,i)=>`${i?'L':'M'}${point.x} ${point.y}`).join(' ');return <div className="team-trend"><svg viewBox="0 0 440 180" role="img" aria-label={`Pessoas ativas: ${series.map(point=>`${monthLabel(point.month)} ${point.active}`).join('; ')}`} preserveAspectRatio="none"><path d="M24 144H416" className="grid"/><path d="M24 104H416 M24 64H416" className="grid faint"/>{points.length>1&&<path d={`${line} L${points[points.length-1].x} 144 L24 144 Z`} className="area"/>}<path d={line} className="line"/>{points.map(point=><g key={point.month}><circle cx={point.x} cy={point.y} r="5" className="dot"><title>{monthLabel(point.month)}: {point.active} pessoas ativas</title></circle><text x={point.x} y="40" textAnchor="middle" className="team-trend-value">{point.active}</text><text x={point.x} y="170" textAnchor="middle">{point.month.slice(5)}/{point.month.slice(2,4)}</text></g>)}</svg></div>}
function errorText(error:unknown){return error instanceof Error?error.message:'Não foi possível concluir a operação.';}
function normalized(row:Partial<Draft>,existing?:Member):Draft{return {...blank,...existing,...row,salary:row.salary??'',salary_review_date:row.salary_review_date??'',gender:row.gender??'',gender_detail:row.gender_detail??'',has_children:row.has_children??'',optional_data_declared:row.optional_data_declared??false};}
function csvCells(raw:string){const lines:string[][]=[];let cells:string[]=[],cell='',quoted=false;const firstLine=raw.split(/\r?\n/,1)[0];const delimiter=firstLine.includes(';')?';':',';for(let i=0;i<raw.length;i++){const char=raw[i];if(char==='"'){if(quoted&&raw[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(char===delimiter&&!quoted){cells.push(cell.trim());cell='';}else if((char==='\n'||char==='\r')&&!quoted){if(char==='\r'&&raw[i+1]==='\n')i++;cells.push(cell.trim());if(cells.some(Boolean))lines.push(cells);cells=[];cell='';}else cell+=char;}if(quoted)throw new Error('Há aspas sem fechamento na planilha.');cells.push(cell.trim());if(cells.some(Boolean))lines.push(cells);return lines;}
const csvColumns=[
  ['codigo_colaborador','employee_code'],['nome_completo','full_name'],['data_admissao','admission_date'],['cargo','job_title'],['senioridade','seniority'],['departamento','department'],['setor','team_area'],['codigo_gestor','manager_code'],['lideranca','is_leader'],['tipo_contratacao','employment_type'],['jornada_semanal_horas','weekly_hours'],['modelo_trabalho','work_model'],['unidade_localidade','location'],['email_corporativo','work_email'],['telefone_profissional','work_phone'],['situacao','status'],['motivo_afastamento','leave_reason'],['data_inicio_afastamento','leave_start_date'],['previsao_retorno','expected_return_date'],['data_desligamento','termination_date'],['iniciativa_desligamento','termination_initiative'],['motivo_desligamento','termination_reason'],['aviso_previo','notice_type'],['remuneracao_atual','salary'],['data_ultima_revisao_salarial','salary_review_date'],['genero','gender'],['identificacao_genero','gender_detail'],['tem_filhos','has_children'],['origem_dados_opcionais_confirmada','optional_data_declared']
] as const;
const csvAliases:Record<string,string>=Object.fromEntries(csvColumns.flatMap(([pt,key])=>[[pt,key],[key,key]]));
function csvHeaderKey(raw:string){const key=raw.trim().toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'');return csvAliases[key]||'';}
function normalizeCsvDate(raw:string,label:string,line:number){const value=raw.trim();if(!value)return'';if(/^\d{4}-\d{2}-\d{2}$/.test(value))return value;const match=value.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);if(!match)throw new Error(`Confira ${label} na linha ${line}: use DD/MM/AAAA.`);const iso=`${match[3]}-${match[2]}-${match[1]}`;const date=new Date(`${iso}T12:00:00`);if(Number.isNaN(date.getTime())||date.getFullYear()!==Number(match[3])||date.getMonth()+1!==Number(match[2])||date.getDate()!==Number(match[1]))throw new Error(`Confira ${label} na linha ${line}: data inválida.`);return iso;}
function csvYes(raw:string){return ['sim','s','yes','true','1'].includes(raw.trim().toLocaleLowerCase('pt-BR'));}
function csvMoney(raw:string){const value=raw.trim();if(!value)return'';const normalized=value.replace(/\s/g,'').replace(/^R\$/i,'').replace(/\./g,'').replace(',','.');const parsed=Number(normalized);if(!Number.isFinite(parsed)||parsed<0)throw new Error('Confira a remuneração informada.');return String(parsed);}
function downloadModel(){const header=csvColumns.map(([label])=>label).join(';')+'\r\n';const blob=new Blob(['\ufeff'+header],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='cali-modelo-colaboradores.csv';a.click();URL.revokeObjectURL(url);}
async function fetchTeamRows(table:'team_members'|'team_month_snapshots'|'team_changes'|'team_member_private',select:string,companyId:string,order:string,ascending=true){
  if(!supabase)throw new Error('Conexão indisponível.');
  const rows:unknown[]=[];
  for(let start=0;start<100000;start+=500){
    const result=await supabase.from(table).select(select).eq('company_id',companyId).order(order,{ascending}).range(start,start+499);
    if(result.error)throw result.error;
    rows.push(...(result.data||[]));
    if((result.data||[]).length<500)return rows;
  }
  throw new Error('A equipe ultrapassou o limite de consulta; contate a CALI para ampliar a leitura.');
}

function columnContent(member:Member,key:ColumnKey,memberMap:Map<string,string>){
  if(key==='status')return <span className={`team-pill ${member.status}`}>{statusLabels[member.status]}</span>;
  if(key==='admission_date'||key==='leave_start_date'||key==='expected_return_date'||key==='termination_date')return dateLabel(member[key] as string|null);
  if(key==='manager_code')return memberMap.get(member.manager_code||'')||member.manager_code||'—';
  if(key==='employment_type')return contractLabels[member.employment_type]||member.employment_type;
  if(key==='weekly_hours')return member.weekly_hours==null?'—':`${member.weekly_hours} h/semana`;
  if(key==='is_leader')return member.is_leader?'Sim':'Não';
  if(key==='leave_reason')return member.leave_reason?(leaveLabels[member.leave_reason]||member.leave_reason):'—';
  if(key==='termination_initiative')return member.termination_initiative?(terminationInitiativeLabels[member.termination_initiative]||member.termination_initiative):'—';
  if(key==='notice_type')return member.notice_type?(noticeLabels[member.notice_type]||member.notice_type):'—';
  return String(member[key]??'—')||'—';
}
